   "fields": [
    {
     "key": "title",
     "text": {
      "en": "Lām over Jīm, Ḥāʾ, or Khāʾ",
      "ar": "Lām over Jīm, Ḥāʾ, or Khāʾ",
      "ur": "Lām over Jīm, Ḥāʾ, or Khāʾ",
      "fr": "Lām over Jīm, Ḥāʾ, or Khāʾ",
      "es": "Lām over Jīm, Ḥāʾ, or Khāʾ"
     },
     "englishOnly": true
    },
    {
     "key": "intro",
     "text": {
      "en": "Lām’s upright stroke leans back and its foot tucks under the bowl of a following jīm, ḥāʾ, or khāʾ rather than continuing along the baseline.",
      "ar": "Lām’s upright stroke leans back and its foot tucks under the bowl of a following jīm, ḥāʾ, or khāʾ rather than continuing along the baseline.",
      "ur": "Lām’s upright stroke leans back and its foot tucks under the bowl of a following jīm, ḥāʾ, or khāʾ rather than continuing along the baseline.",
      "fr": "Lām’s upright stroke leans back and its foot tucks under the bowl of a following jīm, ḥāʾ, or khāʾ rather than continuing along the baseline.",
      "es": "Lām’s upright stroke leans back and its foot tucks under the bowl of a following jīm, ḥāʾ, or khāʾ rather than continuing along the baseline."
     },
     "englishOnly": true
    },
    {
     "key": "fact0",
     "text": {
      "en": "Telling Them Apart: Same bowl, same dot rule as mīm’s stack: no dot is ḥāʾ, a dot below is jīm, a dot above is khāʾ.",
      "ar": "كيف تميّز بينها: Same bowl, same dot rule as mīm’s stack: no dot is ḥāʾ, a dot below is jīm, a dot above is khāʾ.",
      "ur": "ان میں فرق کیسے کریں: Same bowl, same dot rule as mīm’s stack: no dot is ḥāʾ, a dot below is jīm, a dot above is khāʾ.",
      "fr": "Comment les distinguer: Same bowl, same dot rule as mīm’s stack: no dot is ḥāʾ, a dot below is jīm, a dot above is khāʾ.",
      "es": "Cómo distinguirlas: Same bowl, same dot rule as mīm’s stack: no dot is ḥāʾ, a dot below is jīm, a dot above is khāʾ."
     }
    },
    {
     "key": "buildCells",
     "text": {
      "en": "ل ج (Apart)  ·  →  (Joined as One Shape)",
      "ar": "ل ج (منفصلة)  ·  →  (متصلة في شكل واحد)",
      "ur": "ل ج (الگ الگ)  ·  →  (ایک شکل میں جڑے ہوئے)",
      "fr": "ل ج (Séparées)  ·  →  (Unies en une seule forme)",
      "es": "ل ج (Separadas)  ·  →  (Unidas en una sola forma)"
     }
    }
   ],
