   "fields": [
    {
     "key": "title",
     "text": {
      "en": "Mu‘ānaqah",
      "ar": "Mu‘ānaqah",
      "ur": "Mu‘ānaqah",
      "fr": "Mu‘ānaqah",
      "es": "Mu‘ānaqah"
     },
     "englishOnly": true
    },
    {
     "key": "summary",
     "text": {
      "en": "Stop at one, never both",
      "ar": "قف عند إحداهما لا كلتيهما",
      "ur": "ایک پر رکیں، دونوں پر نہیں",
      "fr": "Arrêtez-vous à l’une, jamais aux deux",
      "es": "Detente en una, nunca en ambas"
     }
    },
    {
     "key": "intro",
     "text": {
      "en": "Two stop marks close together, linked — stop at exactly one of the two, never at both and never at neither.",
      "ar": "Two stop marks close together, linked — stop at exactly one of the two, never at both and never at neither.",
      "ur": "Two stop marks close together, linked — stop at exactly one of the two, never at both and never at neither.",
      "fr": "Two stop marks close together, linked — stop at exactly one of the two, never at both and never at neither.",
      "es": "Two stop marks close together, linked — stop at exactly one of the two, never at both and never at neither."
     },
     "englishOnly": true
    },
    {
     "key": "fact0",
     "text": {
      "en": "Requirement: Stop at one, never both",
      "ar": "الحكم: قف عند إحداهما لا كلتيهما",
      "ur": "حکم: ایک پر رکیں، دونوں پر نہیں",
      "fr": "Obligation: Arrêtez-vous à l’une, jamais aux deux",
      "es": "Obligación: Detente en una, nunca en ambas"
     }
    }
   ],
   "arabic": "ۛ ۛ",
   "examples": [
    {
     "text": "ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدٗى لِّلۡمُتَّقِينَ",
     "ref": "2:2"
    },
    {
     "text": "قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَيۡهِمۡۛ أَرۡبَعِينَ سَنَةٗۛ يَتِيهُونَ فِي ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَٰسِقِينَ",
     "ref": "5:26",
     "highlight": "ۡۛ"
    },
    {
     "text": "۞يَـٰٓأَيُّهَا ٱلرَّسُولُ لَا يَحۡزُنكَ ٱلَّذِينَ يُسَٰرِعُونَ فِي ٱلۡكُفۡرِ مِنَ ٱلَّذِينَ قَالُوٓاْ ءَامَنَّا بِأَفۡوَٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِينَ هَادُواْۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِينَ لَمۡ يَأۡتُوكَۖ يُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ يَقُولُونَ إِنۡ أُوتِيتُمۡ هَٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُواْۚ وَمَن يُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَيۡـًٔاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَمۡ يُرِدِ ٱللَّهُ أَن يُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِي ٱلدُّنۡيَا خِزۡيٞۖ وَلَهُمۡ فِي ٱلۡأٓخِرَةِ عَذَابٌ عَظِيمٞ",
     "ref": "5:41",
     "highlight": "ۡۛ"
    }
   ],
